<?php class ActivityController{function index(){require_once __DIR__.'/../models/Activity.php';$activities=Activity::all($_GET);$categories=Activity::categories();view('activities/index',compact('activities','categories'));}function show($id){require_once __DIR__.'/../models/Activity.php';require_once __DIR__.'/../models/Review.php';$activity=Activity::find($id);if(!$activity){http_response_code(404);die('Activité introuvable');}$sessions=Activity::sessions($id);$reviews=Review::approved($id);view('activities/show',compact('activity','sessions','reviews'));}}